"""Restored controls: import, recheck, clear, preview, viewport. Mock recognition only."""
from pathlib import Path
from playwright.sync_api import sync_playwright
import shutil,os,io,wave
R=Path(__file__).resolve().parents[1]
mock="""window.calls=[];window.fetch=async(url,opts)=>{calls.push(String(url));if(String(url).includes('oembed'))return new Response(JSON.stringify({title:'Test video',author_name:'Test channel'}));if(String(url).endsWith('/models'))return new Response(JSON.stringify({data:[{id:'whisper-large-v3'},{id:'whisper-large-v3-turbo'}]}));return new Response(JSON.stringify({language:'en',words:[{word:'hello',start:0.1,end:0.8},{word:'again',start:1,end:1.8}],segments:[]}))};"""
html=(R/'index.html').read_text().replace('<link rel="stylesheet" href="studio.css">','<style>'+(R/'studio.css').read_text()+'</style>').replace('<script src="studio.js" defer></script>','<script>'+mock+'</script><script>'+(R/'studio.js').read_text()+'</script>')
buf=io.BytesIO()
with wave.open(buf,'wb') as f:f.setparams((1,2,16000,0,'NONE','not compressed'));f.writeframes(b'\0\0'*48000)
with sync_playwright() as p:
 b=p.chromium.launch(executable_path=os.environ.get('CHROMIUM_PATH') or shutil.which('chromium'),args=['--no-sandbox']);page=b.new_page(viewport={'width':1366,'height':768});page.route('https://i.ytimg.com/**',lambda route:route.abort());page.on('dialog',lambda d:d.accept());page.set_content(html);page.locator('#welcomeStart').click();page.locator('#apiKey').fill('gsk_mock_123456789012345');page.locator('#screen-3').wait_for(state='visible');page.locator('#url').fill('https://youtu.be/hoNb6HuNmU0');page.locator('#previewTitle').wait_for();page.wait_for_function("document.getElementById('previewTitle').textContent==='Test video'");assert page.locator('#videoPreview').is_visible();assert page.evaluate('document.documentElement.scrollHeight<=innerHeight');page.locator('#fileTab').click();page.locator('#media').set_input_files({'name':'test.wav','mimeType':'audio/wav','buffer':buf.getvalue()});page.locator('#start').click();page.wait_for_function("!document.getElementById('checkWords').disabled");page.locator('#checkWords').click();page.wait_for_function("!document.getElementById('checkWords').disabled");assert page.locator('input[value=maximum]').is_checked();assert page.locator('.word').count()==4;assert page.locator('#progressBox').is_visible();assert page.evaluate('document.documentElement.scrollHeight<=innerHeight');page.locator('#clearTranscript').click();assert page.locator('#transcript').evaluate("e=>e.classList.contains('empty')");page.locator('#importTranscript').set_input_files({'name':'test.srt','mimeType':'text/plain','buffer':b'1\n00:00:01,000 --> 00:00:02,000\nhello world\n'});page.wait_for_function("!document.getElementById('clearTranscript').disabled");assert page.locator('.word').count()==4;assert 'estimated' in page.locator('#timingNote').inner_text();print('Restored workspace: preview, recheck, clear, import, progress, viewport — passed');b.close()
